package com.archos.mediacenter.video.utils;

import android.app.Application;
import android.content.Context;
import androidx.preference.PreferenceManager;
import com.archos.mediacenter.video.utils.backup.*;
import com.archos.mediaprovider.video.VideoOpenHelper;
import java.io.*;
import java.util.*;
import org.json.*;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class) @Config(application=Application.class,sdk=28) @SQLiteMode(SQLiteMode.Mode.NATIVE)
public class MediaMatchIntentsTest {
    private Context app;
    @Before public void setup(){app=RuntimeEnvironment.getApplication();app.deleteDatabase("media.db");PreferenceManager.getDefaultSharedPreferences(app).edit().clear().putString("oauth_token","AUTH_CANARY").commit();}
    private void seed(){try(VideoOpenHelper helper=new VideoOpenHelper(app)){var db=helper.getWritableDatabase();db.execSQL("INSERT INTO files(_id,remote_id,media_type,_data,ArchosMediaScraper_type,ArchosMediaScraper_id,bookmark) VALUES(10,10,3,'file:///PRIVATE_ONE.mkv',11,100,4444),(11,11,3,'file:///PRIVATE_TWO.mkv',11,200,5555)");db.execSQL("INSERT INTO MOVIE(_id,video_id,m_online_id,Nova_pinned,name_movie,plot_movie) VALUES(100,10,123,9,'One','Original facts'),(200,11,456,8,'Two','Other facts')");}}
    private PortablePhysicalReferences physical()throws Exception{return new PortablePhysicalReferences(app,LogicalBackupCatalog.capture(app,()->false).physical);}
    private JSONObject payload(PortablePhysicalReferences refs,long provider)throws Exception{return new JSONObject().put("schema",1).put("rows",new JSONArray().put(new JSONObject().put("physical",refs.reference(10)).put("identity","tmdb:movie:"+provider).put("episodeProvider",JSONObject.NULL)));}
    private Map<Long,PortableMediaMatches.Match> indexed()throws Exception{try(VideoOpenHelper helper=new VideoOpenHelper(app)){return PortableMediaMatches.read(helper.getReadableDatabase());}}
    private void save(MediaMatchIntents.Prepared prepared){var edit=PreferenceManager.getDefaultSharedPreferences(app).edit();for(String key:prepared.keys)edit.remove(key);for(var entry:prepared.values.entrySet())edit.putString(entry.getKey(),(String)entry.getValue());assertTrue(edit.commit());}
    @Test public void preparingReplacementNeverRewritesNativePointersPinsFactsOrPreferences()throws Exception{seed();var before=PreferenceManager.getDefaultSharedPreferences(app).getAll();var refs=physical();var inventory=MediaMatchInventory.capture(app);var prepared=MediaMatchIntents.prepare(before,payload(refs,789),inventory,refs);assertEquals(2,prepared.unresolved);assertEquals(before,PreferenceManager.getDefaultSharedPreferences(app).getAll());assertEquals("tmdb:movie:123",indexed().get(10L).identity);assertEquals("tmdb:movie:456",indexed().get(11L).identity);JSONObject requested=new JSONObject((String)prepared.values.get(MediaMatchIntents.key(10)));assertEquals("tmdb:movie:789",requested.getJSONObject("requested").getString("identity"));assertTrue(new JSONObject((String)prepared.values.get(MediaMatchIntents.key(11))).isNull("requested"));for(Object value:prepared.values.values()){assertFalse(value.toString().contains("PRIVATE_ONE"));assertFalse(value.toString().contains("AUTH_CANARY"));assertFalse(value.toString().contains("Original facts"));}}
    @Test public void pendingBoundCorrectionExportsSavedIntentInsteadOfStaleNativeIdentification()throws Exception{seed();var refs=physical();var inventory=MediaMatchInventory.capture(app);save(MediaMatchIntents.prepare(PreferenceManager.getDefaultSharedPreferences(app).getAll(),payload(refs,789),inventory,refs));var result=MediaMatchIntents.export(app,indexed(),inventory,refs);assertEquals(1,result.getJSONArray("rows").length());assertEquals("tmdb:movie:789",result.getJSONArray("rows").getJSONObject(0).getString("identity"));assertEquals("tmdb:movie:123",indexed().get(10L).identity);assertEquals("AUTH_CANARY",PreferenceManager.getDefaultSharedPreferences(app).getString("oauth_token",null));}
    @Test public void explicitEmptySelectionExportsEmptyWhileNativeClearStillAwaitsItsParticipant()throws Exception{seed();var refs=physical();var inventory=MediaMatchInventory.capture(app);var empty=new JSONObject().put("schema",1).put("rows",new JSONArray());save(MediaMatchIntents.prepare(PreferenceManager.getDefaultSharedPreferences(app).getAll(),empty,inventory,refs));assertEquals(0,MediaMatchIntents.export(app,indexed(),inventory,refs).getJSONArray("rows").length());assertEquals(2,indexed().size());}
    @Test public void laterReceivingIdentificationSupersedesTheGuardedPendingCorrection()throws Exception{seed();var refs=physical();save(MediaMatchIntents.prepare(PreferenceManager.getDefaultSharedPreferences(app).getAll(),payload(refs,789),MediaMatchInventory.capture(app),refs));MediaMatchManualChanges.mark(app,10);try(VideoOpenHelper helper=new VideoOpenHelper(app)){helper.getWritableDatabase().execSQL("UPDATE MOVIE SET m_online_id=999 WHERE _id=100");}var result=MediaMatchIntents.export(app,indexed(),MediaMatchInventory.capture(app),refs);assertEquals(1,result.getJSONArray("rows").length());assertEquals("tmdb:movie:999",result.getJSONArray("rows").getJSONObject(0).getString("identity"));}
    @Test public void movedReceivingFileKeepsOriginalRequestedReferenceUnresolvedInsteadOfRebindingIt()throws Exception{seed();var refs=physical();String original=refs.reference(10);save(MediaMatchIntents.prepare(PreferenceManager.getDefaultSharedPreferences(app).getAll(),payload(refs,789),MediaMatchInventory.capture(app),refs));try(VideoOpenHelper helper=new VideoOpenHelper(app)){helper.getWritableDatabase().execSQL("UPDATE files SET _data='file:///moved.mkv' WHERE _id=10");}var receiving=physical();JSONObject result=MediaMatchIntents.export(app,indexed(),MediaMatchInventory.capture(app),receiving);assertEquals(2,result.getJSONArray("rows").length());Map<String,String> rows=new HashMap<>();for(int i=0;i<result.getJSONArray("rows").length();i++){JSONObject row=result.getJSONArray("rows").getJSONObject(i);rows.put(row.getString("physical"),row.getString("identity"));}assertEquals("tmdb:movie:789",rows.get(original));assertEquals("tmdb:movie:123",rows.get(receiving.reference(10)));}
    @Test public void unboundLogicalIntentRemainsPendingWithoutCreatingNativeStoreOrOrigin()throws Exception{var before=PreferenceManager.getDefaultSharedPreferences(app).getAll();String ref="file:"+"a".repeat(64);JSONObject payload=new JSONObject().put("schema",1).put("rows",new JSONArray().put(new JSONObject().put("physical",ref).put("identity","tmdb:movie:123").put("episodeProvider",JSONObject.NULL)));var prepared=MediaMatchIntents.prepare(before,payload,MediaMatchInventory.capture(app),new PortablePhysicalReferences(app,List.of()));assertEquals(1,prepared.unresolved);assertEquals(1,new JSONObject((String)prepared.values.get(PortableMediaMatches.PENDING)).getJSONArray("rows").length());assertFalse(VideoOpenHelper.getDatabaseFile(app).exists());assertEquals(before,PreferenceManager.getDefaultSharedPreferences(app).getAll());}
    @Test public void invalidPrivateOriginalsFailBeforePreparingAReplacement()throws Exception{seed();var refs=physical();var inventory=MediaMatchInventory.capture(app);Map<String,Object> bad=new HashMap<>(PreferenceManager.getDefaultSharedPreferences(app).getAll());bad.put(MediaMatchIntents.key(10),"{}");try{MediaMatchIntents.prepare(bad,payload(refs,789),inventory,refs);fail();}catch(JSONException expected){}assertEquals("tmdb:movie:123",indexed().get(10L).identity);assertFalse(PreferenceManager.getDefaultSharedPreferences(app).contains(MediaMatchIntents.key(10)));}
}
